contracts/EwaUsdPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title EwaUsdPool
 * @notice Single-LP USDC pool for on-chain earned-wage advances.
 * - Admin (owner or designated admin) sets credit + due date for borrowers.
 * - Borrower draw() moves USDC from pool to borrower.
 * - repay() pulls USDC via ERC20 allowance; collect() lets admin pull if allowance was pre-granted.
 * - LP (owner) can deposit() and withdraw(any amount) from free liquidity at will.
 */
contract EwaUsdPool is Ownable {
    IERC20 public immutable USDC;

    // backend bot / admin who can set credit & collect repayments
    address public admin;

    struct Line {
        uint256 limit;   // max principal allowed
        uint256 debt;    // current outstanding principal
        uint64  dueDate; // unix timestamp
    }

    mapping(address => Line) public lines;

    event AdminUpdated(address indexed admin);
    event CreditSet(address indexed user, uint256 limit, uint64 dueDate);
    event Drawn(address indexed user, uint256 amount);
    event Repaid(address indexed user, uint256 amount);
    event Collected(address indexed user, uint256 amount);
    event Deposited(uint256 amount);
    event Withdrawn(uint256 amount);

    modifier onlyAdmin() {
        require(msg.sender == admin || msg.sender == owner(), "not admin");
        _;
    }

    constructor(address usdc_, address admin_) Ownable(msg.sender) {
        require(usdc_ != address(0), "USDC=0");
        USDC = IERC20(usdc_);
        admin = admin_;
    }

    function setAdmin(address a) external onlyOwner {
        admin = a;
        emit AdminUpdated(a);
    }

    // ===== LP funding =====

    /// @notice Owner deposits USDC after approving this contract.
    function deposit(uint256 amount) external onlyOwner {
        require(amount > 0, "amount=0");
        require(USDC.transferFrom(msg.sender, address(this), amount), "transferFrom fail");
        emit Deposited(amount);
    }

    /// @notice Owner withdraws any free (unused) USDC.
    /// Free liquidity = current USDC balance (debt is already sent out).
    function withdraw(uint256 amount) external onlyOwner {
        require(amount > 0, "amount=0");
        require(USDC.balanceOf(address(this)) >= amount, "insufficient free liquidity");
        require(USDC.transfer(msg.sender, amount), "transfer fail");
        emit Withdrawn(amount);
    }

    // ===== Credit line admin =====

    /// @notice Admin sets/updates the user's credit line and due date.
    /// Requirement for MVP: at most one active loan at a time; allow updating when debt==0.
    function setCredit(address user, uint256 limit, uint64 dueDate) external onlyAdmin {
        require(user != address(0), "user=0");
        Line storage L = lines[user];
        require(L.debt == 0, "close loan first");
        L.limit = limit;
        L.dueDate = dueDate;
        emit CreditSet(user, limit, dueDate);
    }

    // ===== Borrower actions =====

    /// @notice Borrower draws up to their limit if there is free liquidity.
    function draw(uint256 amount) external {
        Line storage L = lines[msg.sender];
        require(amount > 0, "amount=0");
        require(L.limit > 0, "no credit");
        require(L.debt == 0, "one loan at a time");
        require(amount <= L.limit, "exceeds limit");
        require(USDC.balanceOf(address(this)) >= amount, "pool illiquid");

        L.debt = amount;
        require(USDC.transfer(msg.sender, amount), "transfer fail");
        emit Drawn(msg.sender, amount);
    }

    /// @notice Borrower repays (full in MVP).
    function repay(uint256 amount) external {
        Line storage L = lines[msg.sender];
        require(L.debt > 0, "no debt");
        require(amount == L.debt, "must repay full in MVP");

        require(USDC.transferFrom(msg.sender, address(this), amount), "transferFrom fail");
        L.debt = 0;
        emit Repaid(msg.sender, amount);
    }

    // ===== Admin collection (if borrower pre-approved allowance) =====

    function collect(address user) external onlyAdmin {
        Line storage L = lines[user];
        uint256 amt = L.debt;
        require(amt > 0, "no debt");
        require(USDC.transferFrom(user, address(this), amt), "transferFrom fail");
        L.debt = 0;
        emit Collected(user, amt);
    }

    // ===== Views =====

    function lineOf(address user) external view returns (uint256 limit, uint256 debt, uint64 dueDate) {
        Line memory L = lines[user];
        return (L.limit, L.debt, L.dueDate);
    }

    function freeLiquidity() external view returns (uint256) {
        return USDC.balanceOf(address(this));
    }
}

contracts/EwaUsdPoolV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title EwaUsdPoolV2
 * @notice Multi-LP USDC pool for on-chain earned-wage advances.
 * - Multiple LPs can deposit/withdraw independently via LP_ROLE.
 * - Each LP's withdrawal is capped by their net contributed balance.
 * - Admin (owner or designated admin) sets credit + due date for borrowers.
 * - Borrower draw() moves USDC from pool to borrower.
 * - repay() pulls USDC via ERC20 allowance; collect() lets admin pull if allowance was pre-granted.
 * - MVP rules maintained: one active loan per user, free-liquidity checks.
 * 
 * Security features:
 * - ReentrancyGuard on all token-moving functions
 * - Pausable for emergency stops
 * - SafeERC20 for robust token interactions
 * - Role sync with ownership transfers
 * - Due date enforcement on collections
 */
contract EwaUsdPoolV2 is Ownable, AccessControl, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    IERC20 public immutable USDC;

    bytes32 public constant LP_ROLE = keccak256("LP_ROLE");

    // backend bot / admin who can set credit & collect repayments
    address public admin;

    struct Line {
        uint256 limit;   // max principal allowed
        uint256 debt;    // current outstanding principal
        uint64  dueDate; // unix timestamp
    }
    mapping(address => Line) public lines;

    // ---- new: simple LP ledger ----
    mapping(address => uint256) public lpBalance; // raw USDC contributed net of withdrawals
    uint256 public totalLpBalance;                // sum of lpBalance (for visibility)

    event AdminUpdated(address indexed admin);
    event CreditSet(address indexed user, uint256 limit, uint64 dueDate);
    event Drawn(address indexed user, uint256 amount);
    event Repaid(address indexed user, uint256 amount);
    event Collected(address indexed user, uint256 amount);
    event LpAdded(address indexed lp);
    event LpRemoved(address indexed lp);
    event LpDeposited(address indexed lp, uint256 amount);
    event LpWithdrawn(address indexed lp, uint256 amount);

    modifier onlyAdmin() {
        require(msg.sender == admin || msg.sender == owner(), "not admin");
        _;
    }

    constructor(address usdc_, address admin_) Ownable(msg.sender) {
        require(usdc_ != address(0), "USDC=0");
        require(admin_ != address(0), "admin=0");
        USDC = IERC20(usdc_);
        admin = admin_;
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender); // keep owner in sync initially
    }

    // --- governance hygiene: keep AccessControl in sync with ownership ---
    function transferOwnership(address newOwner) public override onlyOwner {
        address prev = owner();
        super.transferOwnership(newOwner);
        // grant DEFAULT_ADMIN_ROLE to new owner, revoke from previous
        _grantRole(DEFAULT_ADMIN_ROLE, newOwner);
        _revokeRole(DEFAULT_ADMIN_ROLE, prev);
    }

    function setAdmin(address a) external onlyOwner {
        require(a != address(0), "admin=0");
        admin = a;
        emit AdminUpdated(a);
    }

    // --- pausability ---
    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    // ---- LP allowlist management ----
    function addLp(address lp) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(LP_ROLE, lp);
        emit LpAdded(lp);
    }
    function removeLp(address lp) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(lpBalance[lp] == 0, "lp has balance");
        _revokeRole(LP_ROLE, lp);
        emit LpRemoved(lp);
    }

    // ---- LP funding (now role-gated, not onlyOwner) ----
    function deposit(uint256 amount) external onlyRole(LP_ROLE) nonReentrant whenNotPaused {
        require(amount > 0, "amount=0");
        USDC.safeTransferFrom(msg.sender, address(this), amount);
        lpBalance[msg.sender] += amount;
        totalLpBalance       += amount;
        emit LpDeposited(msg.sender, amount);
    }

    /// @notice LP withdraws from free (unused) liquidity, capped by their net contributed balance.
    function withdraw(uint256 amount) external onlyRole(LP_ROLE) nonReentrant whenNotPaused {
        require(amount > 0, "amount=0");
        uint256 free = USDC.balanceOf(address(this)); // debt already left contract
        require(free >= amount, "insufficient free liquidity");
        require(lpBalance[msg.sender] >= amount, "exceeds lp balance");
        lpBalance[msg.sender] -= amount;
        totalLpBalance       -= amount;
        USDC.safeTransfer(msg.sender, amount);
        emit LpWithdrawn(msg.sender, amount);
    }

    /// @notice Owner can sweep "excess" USDC not attributable to LP ledger (gifts/mistakes)
    function sweepExcess(address to) external onlyOwner nonReentrant {
        uint256 bal = USDC.balanceOf(address(this));
        if (bal > totalLpBalance) {
            USDC.safeTransfer(to, bal - totalLpBalance);
        }
    }

    // ---- Credit line admin ----
    function setCredit(address user, uint256 limit, uint64 dueDate) external onlyAdmin whenNotPaused {
        require(user != address(0), "user=0");
        require(dueDate > block.timestamp, "dueDate in past");
        Line storage L = lines[user];
        require(L.debt == 0, "close loan first");
        L.limit = limit;
        L.dueDate = dueDate;
        emit CreditSet(user, limit, dueDate);
    }

    // ---- Borrower actions ----
    function draw(uint256 amount) external nonReentrant whenNotPaused {
        Line storage L = lines[msg.sender];
        require(amount > 0, "amount=0");
        require(L.limit > 0, "no credit");
        require(L.debt == 0, "one loan");
        require(amount <= L.limit, "exceeds limit");
        require(USDC.balanceOf(address(this)) >= amount, "pool illiquid");
        L.debt = amount; // effects before interaction
        USDC.safeTransfer(msg.sender, amount);
        emit Drawn(msg.sender, amount);
    }

    function repay(uint256 amount) external nonReentrant whenNotPaused {
        Line storage L = lines[msg.sender];
        require(L.debt > 0, "no debt");
        require(amount == L.debt, "must repay full");
        USDC.safeTransferFrom(msg.sender, address(this), amount);
        L.debt = 0;
        emit Repaid(msg.sender, amount);
    }

    // ---- Admin collection (if allowance pre-approved) ----
    function collect(address user) external onlyAdmin nonReentrant whenNotPaused {
        Line storage L = lines[user];
        uint256 amt = L.debt;
        require(amt > 0, "no debt");
        require(block.timestamp >= L.dueDate, "too early"); // enforce due-date collection
        USDC.safeTransferFrom(user, address(this), amt);
        L.debt = 0;
        emit Collected(user, amt);
    }

    // ---- Views ----
    function lineOf(address user) external view returns (uint256 limit, uint256 debt, uint64 dueDate) {
        Line memory L = lines[user];
        return (L.limit, L.debt, L.dueDate);
    }
    function freeLiquidity() external view returns (uint256) {
        return USDC.balanceOf(address(this));
    }
}

